:root {
  --color-bg: #fdf6ec;
  --color-border: #d9c4a0;
  --color-header-bg: #7a4f2e;
  --color-header-text: #fdf6ec;
  --color-badge-bg: #e8a035;
  --color-badge-text: #3b2008;
  --color-section-label: #9a6a3a;
  --color-item-bg: #fff9f1;
  --color-item-border: #e8d9be;
  --color-bread-name: #3b2008;
  --color-bread-detail: #8a6a4a;
  --color-weight: #7a4f2e;
  --color-footer-bg: #f0e4cc;
  --color-meta-label: #9a6a3a;
  --color-meta-value: #3b2008;
  --color-btn-bg: #7a4f2e;
  --color-btn-text: #fdf6ec;
  --color-btn-hover: #5c3820;
}

.bakery-box {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: 12px;
  width: 440px;
  overflow: hidden;
  font-size: 13px;
}

.box-header {
  background-color: var(--color-header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
}

.box-icon {
  font-size: 24px;
  line-height: 1;
}

.box-title-group {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.box-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--color-header-text);
  margin: 0;
  line-height: 1.1;
  letter-spacing: 0.02em;
}

.box-subtitle {
  font-size: 11px;
  font-weight: 400;
  color: var(--color-header-text);
  margin: 0;
  opacity: 0.8;
  letter-spacing: 0.03em;
}

.box-badge {
  background-color: var(--color-badge-bg);
  color: var(--color-badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  padding: 3px 9px;
  border-radius: 20px;
}

.box-contents {
  padding: 10px 14px;
}

.section-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--color-section-label);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin: 0 0 7px 0;
}

.bread-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.bread-item {
  background-color: var(--color-item-bg);
  border: 1px solid var(--color-item-border);
  border-radius: 7px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
}

.bread-icon {
  font-size: 17px;
  line-height: 1;
  flex-shrink: 0;
}

.bread-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.bread-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-bread-name);
}

.bread-detail {
  font-size: 10px;
  color: var(--color-bread-detail);
}

.bread-weight {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-weight);
  flex-shrink: 0;
}

.box-footer {
  background-color: var(--color-footer-bg);
  border-top: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 14px;
  gap: 10px;
}

.footer-meta {
  display: flex;
  gap: 16px;
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.meta-label {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-meta-label);
}

.meta-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--color-meta-value);
}

.manage-btn {
  background-color: var(--color-btn-bg);
  color: var(--color-btn-text);
  border: none;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 600;
  padding: 6px 13px;
  cursor: pointer;
  white-space: nowrap;
}

.manage-btn:hover {
  background-color: var(--color-btn-hover);
}
